/* Static evidence dashboard. No framework, inference server or remote data service. */
(() => {
  'use strict';
  const datasets = new Map();
  const format = value => value == null ? 'Unavailable' : Number(value).toLocaleString(undefined, { maximumFractionDigits: 2 });
  const node = (tag, text, className) => {
    const element = document.createElement(tag);
    if (text != null) element.textContent = text;
    if (className) element.className = className;
    return element;
  };
  const link = (text, url) => {
    const element = node('a', text);
    // All evidence URLs are generated by the site builder, never entered by visitors.
    if (url && /^https:\/\/github\.com\/SSusantAchary\/mlx-one\//.test(url)) element.href = url;
    return element;
  };
  const table = (headers, rows, caption) => {
    const result = node('table');
    result.append(node('caption', caption));
    const head = node('thead');
    const titles = node('tr');
    headers.forEach(text => { const th = node('th', text); th.scope = 'col'; titles.append(th); });
    head.append(titles);
    result.append(head);
    const body = node('tbody');
    rows.forEach(values => {
      const tr = node('tr');
      values.forEach(value => {
        const cell = node('td');
        cell.append(value instanceof Node ? value : document.createTextNode(String(value ?? 'Unrecorded')));
        tr.append(cell);
      });
      body.append(tr);
    });
    result.append(body);
    return result;
  };
  const details = (title, value) => {
    const element = node('details');
    element.append(node('summary', title));
    element.append(node('pre', JSON.stringify(value, null, 2)));
    return element;
  };
  const badge = (key, data) => node('span', data.status_definitions[key].label, `insights-badge insights-status-${key}`);
  const options = (select, values) => values.forEach(([value, label]) => {
    const option = node('option', label); option.value = value; select.append(option);
  });

  function renderSupport(host, data) {
    const search = host.querySelector('[data-support-search]');
    const modality = host.querySelector('[data-support-modality]');
    const precision = host.querySelector('[data-support-precision]');
    const reset = host.querySelector('[data-support-reset]');
    const models = data.support.models;
    options(modality, [...new Set(models.map(r => r.modality))].sort().map(v => [v, v]));
    options(precision, [...new Set(models.map(r => r.precision))].sort().map(v => [v, v]));
    const render = () => {
      const query = search.value.trim().toLowerCase();
      const rows = models.filter(row => (!modality.value || row.modality === modality.value)
        && (!precision.value || row.precision === precision.value)
        && (!query || [row.model_type, row.checkpoint, row.task, row.precision].join(' ').toLowerCase().includes(query)));
      host.querySelector('[data-support-count]').textContent = `${rows.length} of ${models.length} supported model types shown.`;
      const container = host.querySelector('[data-support-table]');
      container.replaceChildren();
      if (!rows.length) { container.append(node('p', 'No models match. Reset filters to show all supported models.')); return; }
      container.append(table(['Model and checkpoint', 'Primary operations', 'Precision', 'Support and evidence'], rows.map(row => {
        const identity = node('div');
        identity.append(node('strong', row.model_type), node('div', row.checkpoint), node('code', row.revision));
        const evidence = node('div');
        evidence.append(node('span', 'Supported', 'insights-badge insights-status-supported'), document.createTextNode(' '),
          link('Passing task record', `https://github.com/SSusantAchary/mlx-one/blob/${data.source_commit}/${row.evidence}`),
          details('Operations and diagnostics', { operations: row.primary_operations, result_sha256: row.evidence_sha256,
            interfaces: row.interfaces, quality_status: row.quality_status, execution_dtype: row.execution_dtype || 'Recorded profile' }));
        return [identity, row.task, row.precision, evidence];
      }), 'Current native model support: selected checkpoints and primary workflows'));
    };
    [search, modality, precision].forEach(control => {
      control.disabled = false;
      control.addEventListener(control === search ? 'input' : 'change', render);
    });
    reset.disabled = false;
    reset.addEventListener('click', () => { [search, modality, precision].forEach(control => { control.value = ''; }); render(); });
    render();
  }

  function renderRegistrationHistory(host, data) {
    const target = host.querySelector('[data-registration-chart]');
    const registered = data.support.registration_history;
    const admissions = data.support.history;
    if (!registered.points.length) { target.textContent = 'No registry snapshots are available in this checkout.'; return; }
    const points = registered.points;
    const firstTime = Date.parse(points[0].date);
    const lastTime = Math.max(...[...points, ...admissions].map(p => Date.parse(p.date)));
    const maximum = Math.max(...points.map(p => p.registered), ...admissions.map(p => p.supported), 1);
    const x = p => 48 + (Date.parse(p.date) - firstTime) / Math.max(lastTime - firstTime, 86400000) * 680;
    const y = value => 210 - value / maximum * 170;
    const ns = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(ns, 'svg');
    svg.setAttribute('viewBox', '0 0 760 270'); svg.setAttribute('role', 'img');
    const add = (tag, attrs, text) => {
      const el = document.createElementNS(ns, tag);
      Object.entries(attrs).forEach(([key, value]) => el.setAttribute(key, String(value)));
      if (text != null) el.textContent = text;
      svg.append(el); return el;
    };
    add('title', {}, 'Registered native types and separately dated primary-workflow admissions');
    add('desc', {}, data.support.history_note);
    [0, Math.round(maximum / 2), maximum].forEach(value => {
      add('line', { x1: 48, x2: 728, y1: y(value), y2: y(value), class: 'insights-gridline' });
      add('text', { x: 38, y: y(value) + 4, 'text-anchor': 'end', class: 'insights-chart-label' }, value);
    });
    add('path', { d: points.map((p, i) => `${i ? 'H' : 'M'} ${x(p)}${i ? ` V ${y(p.registered)}` : ` ${y(p.registered)}`}`).join(' '),
      fill: 'none', 'stroke-width': 3, class: 'insights-catalog-line' });
    points.forEach(p => {
      const dot = add('circle', { cx: x(p), cy: y(p.registered), r: 3, class: 'insights-catalog-line' });
      const tooltip = document.createElementNS(ns, 'title'); tooltip.textContent = `${p.date}: ${p.registered} registered types`; dot.append(tooltip);
    });
    admissions.forEach(p => {
      const dot = add('circle', { cx: x(p), cy: y(p.supported), r: 6, class: 'insights-admission-point' });
      const tooltip = document.createElementNS(ns, 'title'); tooltip.textContent = `${p.date}: ${p.supported} supported primary workflows`; dot.append(tooltip);
      add('text', { x: x(p), y: y(p.supported) - 14, 'text-anchor': 'end', class: 'insights-chart-label' }, `${p.supported} workflows · ${p.date}`);
    });
    add('text', { x: 48, y: 235, class: 'insights-chart-label' }, points[0].date);
    add('text', { x: 728, y: 235, 'text-anchor': 'end', class: 'insights-chart-label' }, new Date(lastTime).toISOString().slice(0, 10));
    target.append(svg);
    const legend = node('p', null, 'insights-legend');
    legend.append(node('span', '━ Registered native types', 'insights-catalog-key'), node('span', '● Dated passing primary workflows', 'insights-smoke-key'));
    target.append(legend);
    host.querySelector('[data-registration-table]').append(table(
      ['Month', 'Registered types', 'Registry snapshot', 'Passing primary workflows', 'Campaign date'],
      registered.monthly.map(p => {
        const cohort = admissions.filter(a => a.date.slice(0, 7) === p.month).at(-1);
        return [p.month, p.registered, link(p.date, `https://github.com/SSusantAchary/mlx-one/commit/${p.commit}`),
          cohort ? cohort.supported : 'Unrecorded', cohort ? cohort.date : 'Unrecorded'];
      }), 'Monthly recorded coverage: registration and workflow admission use separate evidence'));
  }

  function renderGrowth(host, data) {
    const target = host.querySelector('[data-growth-chart]');
    const points = data.history.points;
    if (!points.length) {
      target.textContent = 'Historical manifest snapshots are unavailable in this checkout.';
      return;
    }
    const ns = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(ns, 'svg');
    svg.setAttribute('viewBox', '0 0 760 270');
    svg.setAttribute('role', 'img');
    const title = document.createElementNS(ns, 'title');
    title.textContent = 'Model catalog and scoped smoke evidence over recorded branch history';
    const desc = document.createElementNS(ns, 'desc');
    const last = points[points.length - 1];
    desc.textContent = `${points.length} manifest snapshots. Latest: ${last.catalog_profiles} catalog profiles and ${last.scoped_smoke_profiles} profiles with scoped smoke evidence. Exact values and commit links follow in the history table.`;
    svg.append(title, desc);
    const firstTime = Date.parse(points[0].date), lastTime = Date.parse(last.date);
    const maximum = Math.max(...points.map(p => p.catalog_profiles), 1);
    const x = p => 48 + (Date.parse(p.date) - firstTime) / Math.max(lastTime - firstTime, 86400000) * 680;
    const y = value => 210 - value / maximum * 170;
    const add = (tag, attrs, text) => {
      const el = document.createElementNS(ns, tag);
      Object.entries(attrs).forEach(([key, value]) => el.setAttribute(key, String(value)));
      if (text != null) el.textContent = text;
      svg.append(el); return el;
    };
    [0, Math.round(maximum / 2), maximum].forEach(value => {
      add('line', { x1: 48, x2: 728, y1: y(value), y2: y(value), class: 'insights-gridline' });
      add('text', { x: 38, y: y(value) + 4, 'text-anchor': 'end', class: 'insights-chart-label' }, value);
    });
    [['catalog_profiles', 'insights-catalog-line'], ['scoped_smoke_profiles', 'insights-smoke-line']].forEach(([key, cls]) => {
      const coordinates = points.map((p, i) => `${i ? 'H' : 'M'} ${x(p)}${i ? ` V ${y(p[key])}` : ` ${y(p[key])}`}`).join(' ');
      add('path', { d: coordinates, fill: 'none', 'stroke-width': 3, class: cls });
      points.forEach(p => {
        const dot = add('circle', { cx: x(p), cy: y(p[key]), r: 3, class: cls });
        const tooltip = document.createElementNS(ns, 'title');
        tooltip.textContent = `${p.date}: ${p[key]} ${key === 'catalog_profiles' ? 'catalog profiles' : 'scoped smoke profiles'}`;
        dot.append(tooltip);
      });
    });
    add('text', { x: 48, y: 235, class: 'insights-chart-label' }, points[0].date);
    add('text', { x: 728, y: 235, 'text-anchor': 'end', class: 'insights-chart-label' }, last.date);
    target.append(svg);
    const legend = node('p', null, 'insights-legend');
    legend.append(node('span', '━ Catalog profiles', 'insights-catalog-key'), node('span', '━ Scoped smoke evidence', 'insights-smoke-key'));
    target.append(legend);
    if (data.history.shallow) target.append(node('p', 'This build has shallow Git history; earlier snapshots may be missing.'));
    host.querySelector('[data-history-table]').append(table(
      ['Recorded date', 'Catalog profiles', 'Scoped smoke profiles', 'Source'],
      points.map(p => [p.date, p.catalog_profiles, p.scoped_smoke_profiles,
        link(p.commit.slice(0, 7), `https://github.com/SSusantAchary/mlx-one/commit/${p.commit}`)]),
      'Historical manifest snapshots'));
  }

  function renderModels(host, data) {
    const search = host.querySelector('[data-model-search]');
    const modality = host.querySelector('[data-model-modality]');
    const status = host.querySelector('[data-model-status]');
    const precision = host.querySelector('[data-model-precision]');
    const reset = host.querySelector('[data-model-reset]');
    options(modality, [...new Set(data.models.map(r => r.modality))].sort().map(v => [v, v]));
    options(status, Object.entries(data.status_definitions).filter(([key]) => data.models.some(r => r.status === key)).map(([key, value]) => [key, value.label]));
    options(precision, [...new Set(data.models.map(r => r.precision))].sort().map(v => [v, v]));
    const render = () => {
      const query = search.value.trim().toLowerCase();
      const rows = data.models.filter(row => (!modality.value || row.modality === modality.value)
        && (!status.value || row.status === status.value)
        && (!precision.value || row.precision === precision.value)
        && (!query || [row.model_id, row.task, row.precision, row.raw_status, data.status_definitions[row.status].label, ...row.notes].join(' ').toLowerCase().includes(query)));
      const container = host.querySelector('[data-model-table]');
      container.replaceChildren();
      host.querySelector('[data-model-count]').textContent = `${rows.length} of ${data.models.length} checkpoint/task profiles shown.`;
      if (!rows.length) { container.append(node('p', 'No profiles match these filters. Reset filters to show all models.')); return; }
      container.append(table(['Checkpoint and task', 'Precision', 'Evidence status', 'First recorded', 'Scope and source'], rows.map(row => {
        const identity = node('div');
        identity.append(node('strong', row.model_id), node('div', row.task, 'insights-muted'), node('code', row.revision || 'Revision unrecorded'));
        const scope = node('div');
        scope.append(link('Source manifest', `https://github.com/SSusantAchary/mlx-one/blob/${data.source_commit}/${row.source}`));
        const record = { raw_status: row.raw_status, release_qualified: row.release_qualified, interfaces: row.interfaces,
          first_smoke_recorded: row.first_smoke_recorded, limitations: row.notes };
        scope.append(details('Evidence boundary', record));
        const first = row.first_recorded;
        return [identity, row.precision, badge(row.status, data), first ? link(first.date, `https://github.com/SSusantAchary/mlx-one/commit/${first.commit}`) : 'Unrecorded', scope];
      }), 'Pinned model profiles and their current evidence boundaries'));
    };
    [search, modality, status, precision].forEach(control => {
      control.disabled = false;
      control.addEventListener(control === search ? 'input' : 'change', render);
    });
    reset.disabled = false;
    reset.addEventListener('click', () => { [search, modality, status, precision].forEach(control => { control.value = ''; }); render(); });
    render();
    const definitions = node('dl', null, 'insights-definitions');
    Object.values(data.status_definitions).forEach(value => definitions.append(node('dt', value.label), node('dd', value.description)));
    host.querySelector('[data-status-definitions]').append(definitions);
    const unrecorded = data.summary.release_qualification_unrecorded;
    host.querySelector('[data-status-definitions]').append(node('p', `${data.summary.release_qualified_true} profiles explicitly record release qualification; ${unrecorded} profiles have no release-qualification field. Missing fields are not approvals.`));
  }

  function bars(container, rows, unit) {
    container.replaceChildren();
    const values = rows.map(row => row.value).filter(value => typeof value === 'number' && Number.isFinite(value));
    const max = values.length ? Math.max(...values, Number.EPSILON) : 1;
    rows.forEach(row => {
      const item = node('div', null, 'insights-bar-item');
      item.append(node('span', row.label, 'insights-bar-label'));
      if (row.value == null) {
        item.append(node('span', row.status || 'Unavailable', 'insights-muted'));
      } else {
        const track = node('div', null, 'insights-bar-track');
        const bar = node('span', null, `insights-bar ${row.variant || ''}`);
        bar.style.width = `${row.value / max * 100}%`;
        track.setAttribute('role', 'img');
        track.setAttribute('aria-label', `${row.label}: ${format(row.value)} ${unit}`);
        track.append(bar);
        item.append(track, node('strong', `${format(row.value)} ${unit}`));
      }
      container.append(item);
    });
  }

  function renderPerformance(host, data) {
    const select = host.querySelector('[data-performance-cohort]');
    options(select, data.performance.map(c => [c.id, c.title]));
    select.disabled = false;
    const render = () => {
      const cohort = data.performance.find(c => c.id === select.value);
      const rows = [...cohort.rows].sort((a, b) => (b.value ?? -1) - (a.value ?? -1));
      host.querySelector('[data-performance-note]').textContent = cohort.note;
      bars(host.querySelector('[data-performance-chart]'), rows.map(r => ({ label: `${r.name || r.model_id} · ${r.precision}`, value: r.value, status: r.status })), cohort.unit);
      const container = host.querySelector('[data-performance-table]');
      container.replaceChildren(table(['Checkpoint', cohort.unit, 'Precision', 'Evidence'], rows.map(r => {
        const evidence = node('div');
        if (r.evidence_url) evidence.append(link('Original JSON', r.evidence_url));
        evidence.append(details('Workload, quality and provenance', { revision: r.revision, status: r.status,
          evidence_sha256: r.evidence_sha256, hardware_and_protocol: r.context, metrics: r.metrics,
          actual_input_tokens: r.actual_input_tokens, actual_output_tokens: r.actual_output_tokens }));
        return [r.model_id, format(r.value), r.precision, evidence];
      }), `${cohort.title} — ${cohort.unit}`));
    };
    select.addEventListener('change', render);
    render();
  }

  function renderBoost(host, data) {
    const rows = data.mlxboost.rows;
    bars(host.querySelector('[data-boost-chart]'), rows.flatMap(r => [
      { label: `${r.model} · flag off`, value: r.off, variant: 'insights-bar-off' },
      { label: `${r.model} · flag on`, value: r.on },
    ]), 'HTTP output tokens/s');
    host.querySelector('[data-boost-table]').append(table(
      ['Checkpoint / precision', 'Flag off', 'Flag on', 'Requests / flag', 'Processes / flag', 'Paired output matches'],
      rows.map(r => [r.model, format(r.off), format(r.on), r.samples_per_flag, r.processes_per_flag,
        r.paired ? `${r.paired.exact_output_matches}/${r.paired.paired_requests}` : 'Not recorded for this cohort']),
      'Complete HTTP SSE wall-time rates; different cohorts remain labeled'));
    host.querySelector('[data-boost-note]').append(document.createTextNode(data.mlxboost.note + ' '), link('Source JSON', data.mlxboost.evidence_url));
  }

  function renderWeeks(host, data) {
    const container = host.querySelector('[data-weekly-milestones]');
    data.weeks.forEach(week => {
      const item = node('details', null, 'insights-week');
      item.append(node('summary', `${week.week} – ${week.end} · ${week.commit_count} first-parent commits`));
      week.milestones.forEach(text => item.append(node('p', `Changelog milestone: ${text}`)));
      const list = node('ul');
      week.commits.forEach(commit => {
        const li = node('li');
        li.append(document.createTextNode(`${commit.date} · `), link(commit.subject, `https://github.com/SSusantAchary/mlx-one/commit/${commit.commit}`));
        list.append(li);
      });
      item.append(list);
      container.append(item);
    });
  }

  async function initialize() {
    const root = document.querySelector('[data-insights-root]');
    if (!root || root.dataset.initialized) return;
    root.dataset.initialized = 'loading';
    const host = root.closest('article') || root.parentElement;
    const provenance = host.querySelector('[data-insights-provenance]');
    try {
      const url = new URL(root.dataset.source, document.baseURI).href;
      if (!datasets.has(url)) datasets.set(url, fetch(url).then(response => {
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        return response.json();
      }).catch(error => { datasets.delete(url); throw error; }));
      const data = await datasets.get(url);
      // Instant navigation may have replaced the article during this request.
      if (!root.isConnected) return;
      if (data.schema_version !== 1) throw new Error('Unsupported dashboard data version');
      provenance.replaceChildren(document.createTextNode('Built from '), link(data.source_commit.slice(0, 7), data.source_url),
        document.createTextNode(` · support campaign ${data.support.release.support_recorded_date} · ${data.support.standard}. Historical catalogs and performance retain their own dates.`));
      renderSupport(host, data);
      renderRegistrationHistory(host, data);
      renderGrowth(host, data);
      renderModels(host, data);
      renderPerformance(host, data);
      renderBoost(host, data);
      renderWeeks(host, data);
      root.dataset.initialized = 'ready';
    } catch (error) {
      provenance.textContent = `Interactive views are unavailable (${error.message}). Use the full catalog below or the linked source reports.`;
      root.dataset.initialized = 'error';
    }
  }
  if (typeof document$ !== 'undefined') document$.subscribe(initialize);
  else if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initialize);
  else initialize();
})();
